ps.pstext:
if !(IsFeatureImplemented(FEAT_ECV) && IsFeatureImplemented(FEAT_AA64)) then
    Undefined();
elsif PSTATE.EL == EL0 then
    if EffectivelyAtEL0NotInHost() && CNTKCTL_EL1().EL0VCTEN == '0' then
        AArch64_SystemAccessTraptoEL1orEL2(0x18);
    elsif EffectivelyAtEL0InHost() && CNTHCTL_EL2().EL0VCTEN == '0' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif EL2Enabled() && EffectivelyAtEL0NotInHost() && CNTHCTL_EL2().EL1TVCT == '1' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    else
        if HaveEL(EL2) && (!EL2Enabled() || EffectivelyAtEL0NotInHost()) then
            X{64}(t) = PhysicalCountInt() - CNTVOFF_EL2();
        elsif HaveEL(EL2) && IsFeatureImplemented(FEAT_AA32EL2) && !ELUsingAArch32(EL2) && (!EL2Enabled() || EffectivelyAtEL0NotInHost()) then
            X{64}(t) = PhysicalCountInt() - CNTVOFF();
        else
            X{64}(t) = PhysicalCountInt();
        end;
    end;
elsif PSTATE.EL == EL1 then
    if EL2Enabled() && CNTHCTL_EL2().EL1TVCT == '1' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    else
        if HaveEL(EL2) then
            X{64}(t) = PhysicalCountInt() - CNTVOFF_EL2();
        else
            X{64}(t) = PhysicalCountInt();
        end;
    end;
elsif PSTATE.EL == EL2 then
    if HaveEL(EL2) && !ELIsInHost(EL2) then
        X{64}(t) = PhysicalCountInt() - CNTVOFF_EL2();
    else
        X{64}(t) = PhysicalCountInt();
    end;
elsif PSTATE.EL == EL3 then
    if HaveEL(EL2) && IsFeatureImplemented(FEAT_AA64EL2) && !ELUsingAArch32(EL2) then
        X{64}(t) = PhysicalCountInt() - CNTVOFF_EL2();
    elsif HaveEL(EL2) && IsFeatureImplemented(FEAT_AA32EL2) then
        X{64}(t) = PhysicalCountInt() - CNTVOFF();
    else
        X{64}(t) = PhysicalCountInt();
    end;
end;
